const data = $('Prepare Email & Summary').first().json;

const WIN1252 = {
  '\u00e4':228,'\u00f6':246,'\u00fc':252,
  '\u00c4':196,'\u00d6':214,'\u00dc':220,
  '\u00df':223,'\u00e9':233,'\u00e8':232,
  '\u00e0':224,'\u00e2':226,'\u00ea':234,
  '\u00fb':251,'\u00ee':238,'\u00ef':239,
  '\u2013':150,'\u2014':151,
  '\u2019':146,'\u201c':147,'\u201d':148,
};

function escPdf(str) {
  let r = '';
  for (const ch of String(str)) {
    if (WIN1252[ch] !== undefined) {
      r += '\\' + WIN1252[ch].toString(8).padStart(3,'0');
    } else if (ch === '\\') { r += '\\\\';
    } else if (ch === '(')  { r += '\\(';
    } else if (ch === ')')  { r += '\\)';
    } else {
      const c = ch.charCodeAt(0);
      r += (c >= 32 && c <= 126) ? ch : '?';
    }
  }
  return r;
}

function wrap(text, max) {
  const words = String(text).split(' ');
  const lines = []; let cur = '';
  for (const w of words) {
    const t = cur ? cur + ' ' + w : w;
    if (t.length > max && cur) { lines.push(cur); cur = w; }
    else cur = t;
  }
  if (cur) lines.push(cur);
  return lines.length ? lines : [''];
}

const PW=595.28, PH=841.89, ML=70.8, MR=524.4, FS=11, LH=16, LSM=14, MAX=80;
const ops = []; let y = 800;

function T(x,yy,str,font,size) {
  const s = escPdf(str);
  if(s) ops.push(`BT /${font} ${size} Tf ${x.toFixed(1)} ${yy.toFixed(1)} Td (${s}) Tj ET`);
}
function TR(str,yy,font,size) {
  T(MR - str.length*size*0.52, yy, str, font, size);
}

T(ML,y,'<APPLICANT_NAME>','FB',FS); y-=LSM;
T(ML,y,'<APPLICANT_ADDRESS>','F',FS); y-=LSM;
T(ML,y,'Mobil: <APPLICANT_PHONE>  E-Mail: <YOUR_EMAIL>','F',FS); y-=22;

const topY=y;
for(const l of [data.company_name,data.hiring_manager,data.company_address,data.location].filter(Boolean)){
  T(ML,y,l,'F',FS); y-=LSM;
}
TR('Ulm, den '+data.date_applied, topY,'F',FS); y-=14;

for(const l of wrap('Bewerbung als '+data.job_title, MAX)){ T(ML,y,l,'FB',FS); y-=LH; }
y-=8;

for(const para of data.cover_letter.split(/\n\n+/)){
  if(y<80) break;
  for(const line of para.trim().split('\n')){
    if(y<80) break;
    if(!line.trim()){y-=6;continue;}
    for(const wl of wrap(line,MAX)){ if(y<80)break; T(ML,y,wl,'F',FS); y-=LH; }
  }
  y-=6;
}

if(y>80){
  y-=4;
  T(ML,y,'Anlagen:','F',FS); y-=LH;
  T(ML,y,'Lebenslauf','F',FS); y-=LH;
  T(ML,y,'Zeugnisse','F',FS);
}

const stream = ops.join('\n');
const fontDict = '/F << /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >> '
               + '/FB << /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>';
const res = `<< /Font << ${fontDict} >> >>`;

function toBytes(s) {
  const a = new Uint8Array(s.length);
  for(let i=0;i<s.length;i++) a[i]=s.charCodeAt(i)&0xff;
  return a;
}

const parts = [];
let offset = 0;
const off = {};

function addObj(id, content) {
  const b = toBytes(content);
  off[id] = offset;
  parts.push(b);
  offset += b.length;
}

const hdrBytes = toBytes('%PDF-1.4\n');
parts.push(hdrBytes); offset += hdrBytes.length;

addObj(1,'1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n');
addObj(2,'2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n');
addObj(3,`3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${PW} ${PH}] /Contents 4 0 R /Resources ${res} >>\nendobj\n`);
addObj(4,`4 0 obj\n<< /Length ${stream.length} >>\nstream\n${stream}\nendstream\nendobj\n`);

const xrefPos = offset;
let xref = 'xref\n0 5\n0000000000 65535 f \n';
for(let i=1;i<=4;i++) xref += String(off[i]).padStart(10,'0')+' 00000 n \n';
xref += `trailer\n<< /Size 5 /Root 1 0 R >>\nstartxref\n${xrefPos}\n%%EOF`;
parts.push(toBytes(xref));

const total = parts.reduce((s,p)=>s+p.length,0);
const allBytes = new Uint8Array(total);
let pos=0;
for(const p of parts){allBytes.set(p,pos);pos+=p.length;}

const B64='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
let b64='';
for(let i=0;i<allBytes.length;i+=3){
  const b0=allBytes[i],b1=allBytes[i+1]||0,b2=allBytes[i+2]||0;
  b64+=B64[b0>>2];
  b64+=B64[((b0&3)<<4)|(b1>>4)];
  b64+=i+1<allBytes.length?B64[((b1&15)<<2)|(b2>>6)]:'=';
  b64+=i+2<allBytes.length?B64[b2&63]:'=';
}

const fname='Anschreiben_'+data.job_title.replace(/[\s\/\\:*?"<>|]/g,'_').substring(0,60)+'.pdf';

return [{
  json: { ...data, anschreiben_filename: fname },
  binary: {
    anschreiben: {
      data: b64,
      mimeType: 'application/pdf',
      fileName: fname,
      fileExtension: 'pdf'
    }
  }
}];

